#!/usr/bin/env python3
"""
Patch .vscode/c_cpp_properties.json to integrate compile_commands.json
with PlatformIO's IntelliSense configuration.

Usage:
    python3 .vscode/patch_intellisense.py

This script is idempotent — safe to run multiple times. It:
  1. Adds "compileCommands" to the PlatformIO configuration so the
     C/C++ extension picks up compile_commands.json.
  2. Compilers the PlatformIO-generated c_cpp_properties.json otherwise
     untouched.

The compile_commands.json (generated by generate_compile_commands.py)
contains entries for test/native/ files. The C/C++ extension applies
these on a per-file basis:
  - Files WITH entries (test files) use those flags.
  - Files WITHOUT entries (src/ files) fall back to the PlatformIO
    config's includePath/defines.

This means test files get native mock IntelliSense and src/ files get
ESP32 IntelliSense — with zero manual configuration switching.

Run this after regenerating with `pio init --ide vscode`.
"""

import json
import sys
from pathlib import Path

PROPS_FILE = Path(__file__).resolve().parent / "c_cpp_properties.json"
COMPILE_COMMANDS = Path("compile_commands.json")


def main() -> int:
    if not PROPS_FILE.exists():
        print(f"Error: {PROPS_FILE} not found.", file=sys.stderr)
        print("Run 'pio init --ide vscode' first.", file=sys.stderr)
        return 1

    with open(PROPS_FILE, "r") as f:
        lines = f.readlines()

    # Strip leading comment lines (PlatformIO adds // comments which aren't valid JSON)
    json_start = 0
    for i, line in enumerate(lines):
        if line.strip().startswith("{"):
            json_start = i
            break

    props = json.loads("".join(lines[json_start:]))
    configs = props.get("configurations", [])

    modified = False

    for config in configs:
        if config.get("name") == "PlatformIO":
            existing = config.get("compileCommands")
            expected = "${workspaceFolder}/.vscode/compile_commands.json"
            if existing != expected:
                config["compileCommands"] = expected
                modified = True
                print(f"Added compileCommands to 'PlatformIO' configuration.")
            else:
                print(f"'PlatformIO' already has compileCommands configured.")

    if not modified and any(c.get("name") == "PlatformIO" for c in configs):
        pass  # Already up to date
    elif not any(c.get("name") == "PlatformIO" for c in configs):
        print("Warning: No 'PlatformIO' configuration found.", file=sys.stderr)

    # Reconstruct file, preserving PlatformIO comment header
    header = "".join(lines[:json_start])
    body = json.dumps(props, indent=4)

    with open(PROPS_FILE, "w") as f:
        f.write(header)
        f.write(body)
        f.write("\n")

    print(f"Patched {PROPS_FILE}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
